    fun getItemsByCategory(category: String): List<WildRiftItem> =
        list.filter { it.category.equals(category, ignoreCase = true) }
        
    fun searchItems(query: String): List<WildRiftItem> {
        val q = query.lowercase().trim()
        return list.filter {
            it.name.lowercase().contains(q) || it.nameEn.lowercase().contains(q)
        }
    }

    fun getItemByName(name: String): WildRiftItem? {
        val q = name.lowercase().trim()
        return list.find { it.name.lowercase() == q || it.nameEn.lowercase() == q }
            ?: list.find { it.name.lowercase().contains(q) || it.nameEn.lowercase().contains(q) }
    }

    fun getItemIconByName(name: String): String {
        return getItemByName(name)?.iconUrl ?: ""
    }
